def compute(vars):
    consumer_related = vars["v1"] + vars["v2"]
    total_exposure = vars["v3"]
    if total_exposure == 0:
        return None
    result = consumer_related / total_exposure
    return {
        "value": result,
        "trace": {
            "consumer_related_exposure": consumer_related,
            "total_corporate_lending_exposure": total_exposure,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
